const envelope = $json;
const input = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
const headers = envelope.headers || {};
const errors = [];
const clean = (value) => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '';
const name = clean(input.name);
const company = clean(input.company);
const email = clean(input.email).toLowerCase();
const rawPhone = clean(input.phone);
let phone = '';
if (rawPhone) {
  const hasPlus = rawPhone.startsWith('+');
  const digits = rawPhone.replace(/\D/g, '');
  phone = hasPlus ? `+${digits}` : (digits.length === 10 ? `+91${digits}` : `+${digits}`);
}
if (name.length < 2 || name.length > 100) errors.push({ field: 'name', message: 'name must contain 2 to 100 characters' });
if (company.length > 100) errors.push({ field: 'company', message: 'company must not exceed 100 characters' });
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push({ field: 'email', message: 'email must be a valid address' });
if (phone && !/^\+[1-9]\d{7,14}$/.test(phone)) errors.push({ field: 'phone', message: 'phone must be a valid 8 to 15 digit international number (10 digits defaults to +91)' });
if (!email && !phone) errors.push({ field: 'contact', message: 'provide at least one valid email or phone' });
const budget = input.budget === undefined || input.budget === null || input.budget === '' ? null : Number(input.budget);
if (budget !== null && (!Number.isFinite(budget) || budget < 0)) errors.push({ field: 'budget', message: 'budget must be a non-negative number' });
const timelineDays = input.timelineDays === undefined || input.timelineDays === null || input.timelineDays === '' ? null : Number(input.timelineDays);
if (timelineDays !== null && (!Number.isInteger(timelineDays) || timelineDays < 1 || timelineDays > 3650)) errors.push({ field: 'timelineDays', message: 'timelineDays must be an integer from 1 to 3650' });
const suppliedKey = clean(headers['x-idempotency-key'] || headers['X-Idempotency-Key']);
if (suppliedKey && !/^[A-Za-z0-9._:-]{8,100}$/.test(suppliedKey)) errors.push({ field: 'x-idempotency-key', message: 'x-idempotency-key must be 8 to 100 URL-safe characters' });
if (errors.length) return [{ json: { valid: false, response: { ok: false, error: 'VALIDATION_ERROR', message: 'Fix the listed fields and submit again.', details: errors } } }];
const identity = `${email}|${phone}|${name.toLowerCase()}`;
let h1 = 2166136261, h2 = 2246822519;
for (let i = 0; i < identity.length; i++) { h1 = Math.imul(h1 ^ identity.charCodeAt(i), 16777619); h2 = Math.imul(h2 ^ identity.charCodeAt(i), 3266489917); }
const generatedKey = `lead-${(h1 >>> 0).toString(16).padStart(8, '0')}${(h2 >>> 0).toString(16).padStart(8, '0')}`;
return [{ json: { valid: true, idempotencyKey: suppliedKey || generatedKey, lead: { name, company: company || null, email: email || null, phone: phone || null, budget, timelineDays, source: clean(input.source) || 'unknown', message: clean(input.message) || null } } }];

const SCORE_CONFIG = {
  qualificationThreshold: 50,
  rules: {
    companyPresent: 10,
    businessEmail: 15,
    phonePresent: 10,
    budgetAtLeast100000: 30,
    budgetAtLeast50000: 20,
    timelineAtMost30Days: 25,
    timelineAtMost90Days: 15,
    intentKeyword: 15
  },
  consumerEmailDomains: ['gmail.com', 'outlook.com', 'hotmail.com', 'yahoo.com'],
  intentKeywords: ['automation', 'workflow', 'integration', 'crm', 'lead routing']
};
const lead = $json.lead;
let score = 0;
const reasons = [];
const add = (rule, condition, label) => { if (condition) { score += SCORE_CONFIG.rules[rule]; reasons.push({ rule, points: SCORE_CONFIG.rules[rule], label }); } };
add('companyPresent', Boolean(lead.company), 'Company supplied');
const domain = lead.email ? lead.email.split('@')[1] : '';
add('businessEmail', Boolean(domain) && !SCORE_CONFIG.consumerEmailDomains.includes(domain), 'Business email');
add('phonePresent', Boolean(lead.phone), 'Phone supplied');
add('budgetAtLeast100000', lead.budget >= 100000, 'Budget at least 100000');
if (!(lead.budget >= 100000)) add('budgetAtLeast50000', lead.budget >= 50000, 'Budget at least 50000');
add('timelineAtMost30Days', lead.timelineDays !== null && lead.timelineDays <= 30, 'Timeline at most 30 days');
if (!(lead.timelineDays !== null && lead.timelineDays <= 30)) add('timelineAtMost90Days', lead.timelineDays !== null && lead.timelineDays <= 90, 'Timeline at most 90 days');
const haystack = `${lead.message || ''} ${lead.source || ''}`.toLowerCase();
add('intentKeyword', SCORE_CONFIG.intentKeywords.some((keyword) => haystack.includes(keyword)), 'Automation intent');
return [{ json: { idempotencyKey: $json.idempotencyKey, lead: { ...lead, score, qualification: score >= SCORE_CONFIG.qualificationThreshold ? 'qualified' : 'nurture', scoreReasons: reasons } } }];
